@namespace sv_0e8c167bcba74a6c9882779b7a4414a4.Components.Pages.Catalog

<div class="catalog-toolbar">
    <div class="toolbar-sort">
        <label for="sort-select">Sort by:</label>
        <select id="sort-select" value="@SortBy" @onchange="HandleSortChange">
            <option value="price_asc">Price: Low to High</option>
            <option value="price_desc">Price: High to Low</option>
            <option value="name_asc">Name: A-Z</option>
            <option value="rating_desc">Rating: Highest</option>
        </select>
    </div>
    <div class="toolbar-info">
        Showing @RangeStart–@RangeEnd of @TotalCount products
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public string SortBy { get; set; } = "price_asc";

    [Parameter]
    public int TotalCount { get; set; }

    [Parameter]
    public int Page { get; set; }

    [Parameter]
    public int PageSize { get; set; }

    [Parameter]
    public EventCallback<string> OnSortChanged { get; set; }

    private int RangeStart => TotalCount == 0 ? 0 : (Page - 1) * PageSize + 1;
    private int RangeEnd => Math.Min(Page * PageSize, TotalCount);

    private async Task HandleSortChange(ChangeEventArgs e)
    {
        await OnSortChanged.InvokeAsync(e.Value?.ToString() ?? "price_asc");
    }
}

@namespace sv_0e8c167bcba74a6c9882779b7a4414a4.Components.Pages.Catalog

<nav class="catalog-pagination" aria-label="Product pagination">
    <button class="btn-page" disabled="@(CurrentPage <= 1)" @onclick="@(() => GoToPage(CurrentPage - 1))">
        Previous
    </button>

    @for (int i = 1; i <= TotalPages; i++)
    {
        var pageNum = i;
        <button class="btn-page @(pageNum == CurrentPage ? "active" : "")"
                @onclick="@(() => GoToPage(pageNum))">
            @pageNum
        </button>
    }

    <button class="btn-page" disabled="@(CurrentPage >= TotalPages)" @onclick="@(() => GoToPage(CurrentPage + 1))">
        Next
    </button>
</nav>

@code {
    [Parameter]
    public int CurrentPage { get; set; } = 1;

    [Parameter]
    public int TotalPages { get; set; } = 1;

    [Parameter]
    public EventCallback<int> OnPageChanged { get; set; }

    private async Task GoToPage(int page)
    {
        if (page >= 1 && page <= TotalPages)
        {
            await OnPageChanged.InvokeAsync(page);
        }
    }
}

@page "/catalog"
@namespace sv_0e8c167bcba74a6c9882779b7a4414a4.Components.Pages.Catalog
@using sv_0e8c167bcba74a6c9882779b7a4414a4
@inject IProductService ProductService
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<div class="catalog-page">
    <CatalogFilters Categories="categories"
                    OnApply="HandleApplyFilters"
                    OnClear="HandleClearFilters" />

    <main class="catalog-main">
        @if (isLoading)
        {
            <div class="catalog-loading">
                <p>Loading products…</p>
            </div>
        }
        else if (errorMessage is not null)
        {
            <div class="catalog-error">
                <p>Something went wrong: @errorMessage</p>
                <button @onclick="LoadProductsAsync">Retry</button>
            </div>
        }
        else if (products.Count == 0)
        {
            <div class="catalog-empty">
                <p>No products found matching your criteria.</p>
            </div>
        }
        else
        {
            <CatalogToolbar SortBy="@sortBy"
                            TotalCount="totalCount"
                            Page="currentPage"
                            PageSize="pageSize"
                            OnSortChanged="HandleSortChanged" />

            <ProductGrid Products="products"
                         OnProductSelected="HandleProductSelected"
                         OnAddToCart="HandleAddToCart" />

            <CatalogPagination CurrentPage="currentPage"
                               TotalPages="totalPages"
                               OnPageChanged="HandlePageChanged" />
        }
    </main>
</div>

@code {
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }

    private List<Product> products = [];
    private List<string> categories = [];
    private ProductFilter currentFilter = new(null, null, null, false);
    private string sortBy = "price_asc";
    private int currentPage = 1;
    private int pageSize = 12;
    private int totalCount;
    private int totalPages;
    private bool isLoading = true;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        try
        {
            var categoriesTask = ProductService.GetCategoriesAsync();
            var productsTask = ProductService.SearchAsync(currentFilter, sortBy, currentPage, pageSize);

            await Task.WhenAll(categoriesTask, productsTask);

            categories = await categoriesTask;
            ApplyResult(await productsTask);
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task LoadProductsAsync()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            var result = await ProductService.SearchAsync(currentFilter, sortBy, currentPage, pageSize);
            ApplyResult(result);
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ApplyResult(PagedResult<Product> result)
    {
        products = result.Items;
        totalCount = result.TotalCount;
        totalPages = (int)Math.Ceiling((double)result.TotalCount / pageSize);
    }

    private async Task HandleApplyFilters(ProductFilter filter)
    {
        currentFilter = filter;
        currentPage = 1;
        await LoadProductsAsync();
    }

    private async Task HandleClearFilters()
    {
        currentFilter = new ProductFilter(null, null, null, false);
        currentPage = 1;
        await LoadProductsAsync();
    }

    private async Task HandleSortChanged(string newSort)
    {
        sortBy = newSort;
        currentPage = 1;
        await LoadProductsAsync();
    }

    private async Task HandlePageChanged(int page)
    {
        currentPage = page;
        await LoadProductsAsync();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private async Task HandleAddToCart(Product product)
    {
        await OnAddToCart.InvokeAsync(product);
    }
}

